impl Solution {
    pub fn maximum_beauty(flowers: Vec<i32>, new_flowers: i64, target: i32, full: i32, partial: i32) -> i64 {
        let n = flowers.len();
        let target = target as i64;
        let full = full as i64;
        let partial = partial as i64;

        // Separate flowers into two groups:
        // - those already >= target (complete)
        // - those < target (incomplete)
        // For incomplete, cap at target-1 (since >= target means complete)
        let mut incomplete: Vec<i64> = flowers.iter()
            .map(|&f| f as i64)
            .filter(|&f| f < target)
            .map(|f| f.min(target - 1))
            .collect();

        // Count how many are already complete
        let mut complete_count = flowers.iter().filter(|&&f| (f as i64) >= target).count() as i64;

        // If all are complete, total beauty = n * full, partial term = 0
        if complete_count == n as i64 {
            return (n as i64) * full;
        }

        // Sort incomplete ascending
        incomplete.sort_unstable();

        // Prefix sums for incomplete to quickly compute cost to raise minimum to some level
        // prefix[i] = sum of incomplete[0..i]
        let mut prefix = vec![0i64; incomplete.len() + 1];
        for i in 0..incomplete.len() {
            prefix[i + 1] = prefix[i] + incomplete[i];
        }

        // Sort flowers ascending for complete calculation (we will try to make some incomplete complete)
        // Actually, we only need incomplete sorted, and we know complete count.
        // We'll try to convert some incomplete to complete from the right side (largest incomplete first)
        // So sort incomplete ascending is fine.

        // We'll try all possible numbers of complete beds from complete_count up to n
        // For each number of complete beds c, we try to make last c - complete_count incomplete beds complete
        // Then with remaining flowers, raise the minimum of the rest incomplete beds as high as possible (up to target-1)
        // If c == n, partial term = 0

        let mut res = 0i64;
        let total_incomplete = incomplete.len() as i64;

        // To make some incomplete beds complete, we pick from the largest incomplete beds
        // So incomplete is sorted ascending, largest are at the end

        // We'll try c from complete_count to complete_count + total_incomplete (max n)
        // But c cannot exceed n
        let max_complete = complete_count + total_incomplete;
        let max_complete = max_complete.min(n as i64);

        // Precompute suffix sums of cost to make incomplete beds complete
        // cost to make incomplete[i] complete = target - incomplete[i]
        let mut suffix_complete_cost = vec![0i64; incomplete.len() + 1];
        for i in (0..incomplete.len()).rev() {
            suffix_complete_cost[i] = suffix_complete_cost[i + 1] + (target - incomplete[i]);
        }

        // Binary search helper: given a minimum level x, compute cost to raise all incomplete beds (except those made complete) to at least x
        // The incomplete beds considered are incomplete[0..incomplete.len()-complete_to_make]
        // We want to find how many beds have value < x, and sum cost to raise them to x
        // cost = x * count_less - sum_of_values_less
        // We can use prefix sums to get sum_of_values_less and count_less

        // We'll iterate c from complete_count to max_complete:
        // complete_to_make = c - complete_count
        // incomplete beds left = incomplete.len() - complete_to_make
        // We try to raise minimum of these incomplete beds as high as possible with remaining flowers

        for c in complete_count..=max_complete {
            let complete_to_make = c - complete_count;
            if complete_to_make > total_incomplete {
                break;
            }
            let incomplete_left = (total_incomplete - complete_to_make) as usize;

            // Cost to make complete_to_make beds complete (largest incomplete_to_make beds)
            let cost_complete = suffix_complete_cost[incomplete.len() - complete_to_make as usize];

            if cost_complete > new_flowers {
                // Not enough flowers to make these many complete
                continue;
            }

            let remain = new_flowers - cost_complete;

            // If incomplete_left == 0, partial term = 0
            if incomplete_left == 0 {
                // All beds complete
                let total_beauty = c * full;
                if total_beauty > res {
                    res = total_beauty;
                }
                continue;
            }

            // We want to raise minimum of incomplete[0..incomplete_left] as high as possible (up to target-1)
            // Use binary search on x in [incomplete[0], target-1]
            // incomplete is sorted ascending, so min is incomplete[0]

            let mut low = incomplete[0];
            let mut high = target - 1;
            if low > high {
                // min already >= target-1, partial term = 0
                let total_beauty = c * full;
                if total_beauty > res {
                    res = total_beauty;
                }
                continue;
            }

            // Binary search max x s.t cost to raise incomplete[0..incomplete_left] to x <= remain
            while low < high {
                let mid = (low + high + 1) / 2;
                // Find how many beds have value < mid
                // Use binary search in incomplete[0..incomplete_left]
                let pos = incomplete[..incomplete_left].binary_search(&mid).unwrap_or_else(|x| x);
                // cost = mid * pos - prefix[pos]
                let cost = mid * (pos as i64) - prefix[pos];
                if cost <= remain {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }

            let total_beauty = c * full + low * partial;
            if total_beauty > res {
                res = total_beauty;
            }
        }

        res
    }
